questionvariables.text:
scenario : rand(3);
ta : if scenario=0 then "even" elseif scenario=1 then "odd" else "neither";
/* Booleans wrapped in is() so each option carries true or false, not an unevaluated equation */
opts : [["even", is(scenario=0), "Even (symmetric about the y-axis)"],["odd", is(scenario=1), "Odd (symmetric about the origin)"],["neither", is(scenario=2), "Neither"]];
